PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, salt TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL UNIQUE REFERENCES users(id), daily_limit INTEGER NOT NULL DEFAULT 30, timezone TEXT NOT NULL DEFAULT 'Asia/Ho_Chi_Minh');
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE pairings (code_hash TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), expires_at INTEGER NOT NULL, used_at INTEGER);
CREATE TABLE devices (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, last_seen INTEGER NOT NULL, facebook_ready INTEGER NOT NULL DEFAULT 0, revoked_at INTEGER);
CREATE UNIQUE INDEX one_device ON devices(workspace_id) WHERE revoked_at IS NULL;
CREATE TABLE campaigns (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, data TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE INDEX campaign_owner ON campaigns(workspace_id);
CREATE TABLE assets (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), object_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX asset_owner ON assets(workspace_id);
CREATE TABLE jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), campaign_id TEXT NOT NULL REFERENCES campaigns(id), slot TEXT NOT NULL UNIQUE, snapshot TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', device_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, lease_until INTEGER, cancel_requested INTEGER NOT NULL DEFAULT 0, result TEXT);
CREATE INDEX job_owner ON jobs(workspace_id, created_at);
CREATE UNIQUE INDEX one_running_job ON jobs(workspace_id) WHERE status IN ('running', 'needs_review');
CREATE TABLE attempts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), job_id TEXT NOT NULL REFERENCES jobs(id), group_url TEXT NOT NULL, status TEXT NOT NULL, day TEXT NOT NULL, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX attempt_day ON attempts(workspace_id, day, status);
CREATE TABLE job_events (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), workspace_id TEXT NOT NULL REFERENCES workspaces(id), text TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX event_job ON job_events(job_id, created_at);
